import java.util.*;import java.math.*;public class Study {public static Object money(String s){return Double.valueOf(s);}public static Object transform(List<?>p,Object r){List<Double>out=new ArrayList<>();for(Object v:p){double product=((Double)v)*(1.0+((Double)r));BigDecimal rounded=new BigDecimal(product).setScale(2,RoundingMode.HALF_UP);out.add(rounded.doubleValue());}return out;}public static List<?>values(Object r){return (List<?>)r;}public static Object representation(Object v){return v;}}